enum class IndicConjunctBreakProperty : uint8_t {
  None      =  0,
  LINKER    =  1,
  CONSONANT =  2,
  EXTEND    =  3,
};

struct RawCodePoint {
  std::string_view original;
  std::string_view normal;
  std::string_view folded_case;
  std::string_view swapped_case;
  bool is_letter;
  bool is_punctuation;
  bool is_uppercase;
  uint8_t grapheme_break_property;
  uint8_t combining_class;
  uint8_t indic_conjunct_break_property;
};

class CodePoint {
public:
  YCM_EXPORT explicit CodePoint( std::string_view code_point );
  // Make class noncopyable
  CodePoint( const CodePoint& ) = delete;
  CodePoint& operator=( const CodePoint& ) = delete;
  CodePoint( CodePoint&& ) = default;
  CodePoint& operator=( CodePoint&& ) = default;

  inline const std::string &Normal() const {
    return normal_;
  }

  inline const std::string &FoldedCase() const {
    return folded_case_;
  }

  inline const std::string &SwappedCase() const {
    return swapped_case_;
  }

  inline bool IsLetter() const {
    return is_letter_;
  }

  inline bool IsPunctuation() const {
    return is_punctuation_;
  }

  inline bool IsUppercase() const {
    return is_uppercase_;
  }

  inline GraphemeBreakProperty GetGraphemeBreakProperty() const {
    return grapheme_break_property_;
  }

  inline uint8_t CombiningClass() const {
    return combining_class_;
  }

  inline IndicConjunctBreakProperty GetIndicConjunctBreakProperty() const {
    return indic_conjunct_break_property_;
  }

  inline bool operator< ( const CodePoint &other ) const {
    return combining_class_ < other.combining_class_;
  }

private:
  explicit CodePoint( RawCodePoint&& code_point );

  std::string normal_;
  std::string folded_case_;
  std::string swapped_case_;
  bool is_letter_;
  bool is_punctuation_;
  bool is_uppercase_;
  GraphemeBreakProperty grapheme_break_property_;
  uint8_t combining_class_;
  IndicConjunctBreakProperty indic_conjunct_break_property_;
};

struct YCM_EXPORT UnicodeDecodeError : std::runtime_error {
  using std::runtime_error::runtime_error;
  const char* what() const noexcept override;
};

class Character {
public:
  YCM_EXPORT explicit Character( std::string_view character );
  // Make class noncopyable
  Character( const Character& ) = delete;
  Character& operator=( const Character& ) = delete;
  Character( Character&& ) = default;
  Character& operator=( Character&& ) = default;

  inline const std::string &Normal() const {
    return normal_;
  }

  inline const std::string &Base() const {
    return base_;
  }

  inline const std::string &FoldedCase() const {
    return folded_case_;
  }

  inline const std::string &SwappedCase() const {
    return swapped_case_;
  }

  inline bool IsBase() const {
    return is_base_;
  }

  inline bool IsLetter() const {
    return is_letter_;
  }

  inline bool IsPunctuation() const {
    return is_punctuation_;
  }

  inline bool IsUppercase() const {
    return is_uppercase_;
  }

  inline bool operator== ( const Character &other ) const {
    return normal_ == other.normal_;
  }

  inline bool EqualsBase( const Character &other ) const {
    return base_ == other.base_;
  }

  inline bool EqualsIgnoreCase( const Character &other ) const {
    return folded_case_ == other.folded_case_;
  }

  // Smart base matching on top of smart case matching, e.g.:
  //  - e matches e, é, E, É;
  //  - E matches E, É but not e, é;
  //  - é matches é, É but not e, E;
  //  - É matches É but not e, é, E.
  inline bool MatchesSmart( const Character &other ) const {
    return ( is_base_ && EqualsBase( other ) &&
             ( !is_uppercase_ || other.is_uppercase_ ) ) ||
           ( !is_uppercase_ && EqualsIgnoreCase( other ) ) ||
           normal_ == other.normal_;
  }

private:
  std::string normal_;
  std::string base_;
  std::string folded_case_;
  std::string swapped_case_;
  bool is_base_;
  bool is_letter_;
  bool is_punctuation_;
  bool is_uppercase_;
};

class Word {
public:
  YCM_EXPORT explicit Word( std::string&& text );
  // Make class noncopyable
protected:
  Word( const Word& ) = default;
  Word& operator=( const Word& ) = default;
public:
  Word( Word&& ) = default;
  Word& operator=( Word&& ) = default;
  ~Word() = default;

  inline const CharacterSequence &Characters() const {
    return characters_;
  }

  inline const std::string &Text() const {
    return text_;
  }

  inline size_t Length() const {
    return characters_.size();
  }

  // Returns true if the word contains the bytes from another word (it may also
  // contain other bytes).
  inline bool ContainsBytes( const Word &other ) const {
    return ( bytes_present_ & other.bytes_present_ ) == other.bytes_present_;
  }

  inline bool IsEmpty() const {
    return characters_.empty();
  }

private:
  void BreakIntoCharacters();
  void ComputeBytesPresent();

  std::string text_;
  CharacterSequence characters_;
  Bitset bytes_present_;
};

