// Generate a valid single Unicode scalar value and encode it to UTF-8 to satisfy
// the constructor requirement that input be exactly one UTF-8 code point.
uint32_t scalar = *FUZZ_PARAM(uint32_t) % 0x110000; // [0, 0x10FFFF]
// Avoid surrogate range; map into a safe ASCII letter if we hit it to ensure validity.
if (scalar >= 0xD800 && scalar <= 0xDFFF) { scalar = 'A'; }
// Optionally avoid noncharacters; map a couple of them to a safe code point.
if ((scalar & 0xFFFEu) == 0xFFFEu || (scalar >= 0xFDD0 && scalar <= 0xFDEF)) { scalar = 'B'; }

std::string utf8;
utf8.reserve(4);
if (scalar <= 0x7Fu) {
  utf8.push_back(static_cast<char>(scalar));
} else if (scalar <= 0x7FFu) {
  utf8.push_back(static_cast<char>(0xC0 | ((scalar >> 6) & 0x1F)));
  utf8.push_back(static_cast<char>(0x80 | (scalar & 0x3F)));
} else if (scalar <= 0xFFFFu) {
  utf8.push_back(static_cast<char>(0xE0 | ((scalar >> 12) & 0x0F)));
  utf8.push_back(static_cast<char>(0x80 | ((scalar >> 6) & 0x3F)));
  utf8.push_back(static_cast<char>(0x80 | (scalar & 0x3F)));
} else {
  utf8.push_back(static_cast<char>(0xF0 | ((scalar >> 18) & 0x07)));
  utf8.push_back(static_cast<char>(0x80 | ((scalar >> 12) & 0x3F)));
  utf8.push_back(static_cast<char>(0x80 | ((scalar >> 6) & 0x3F)));
  utf8.push_back(static_cast<char>(0x80 | (scalar & 0x3F)));
}

// Construct the CodePoint; this must not throw given we ensured valid one-code-point UTF-8.
YouCompleteMe::CodePoint *code_point = new YouCompleteMe::CodePoint(std::string_view(utf8));
// Track liveness for downstream accessors.
FUZZ_SET_ATTR_INT(code_point, "alive", 1);
// Output: ownership passes to the fuzzer runtime.

// Ensure the input object was successfully constructed and is alive.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
// Access the normalized form; reference remains valid while code_point lives.
const std::string &n = code_point->Normal();
// Property: a valid single code point normalization should be non-empty.
FUZZ_ASSERT(!n.empty(), "Normal() returned empty string for a valid CodePoint");
// Return the object back to the pool.

// Validate object lifetime.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
const std::string &fc = code_point->FoldedCase();
FUZZ_ASSERT(!fc.empty(), "FoldedCase() returned empty string for a valid CodePoint");
// Return the object unchanged.

// Validate object lifetime.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
const std::string &sc = code_point->SwappedCase();
FUZZ_ASSERT(!sc.empty(), "SwappedCase() returned empty string for a valid CodePoint");
// Return the object unchanged.

// Validate input object.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
// Invoke the query; boolean value has no additional constraints.
( void ) code_point->IsLetter();
// Return object unchanged.

// Validate input object.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
( void ) code_point->IsPunctuation();
// Return object unchanged.

// Validate input object.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
( void ) code_point->IsUppercase();
// Return object unchanged.

// Validate input object.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
( void ) code_point->GetGraphemeBreakProperty();
// Return object unchanged.

// Validate input object.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
uint8_t ccc = code_point->CombiningClass();
// Property: Canonical Combining Class is an 8-bit value by API.
FUZZ_ASSERT(ccc <= 0xFF, "CombiningClass() returned value out of uint8_t range");
// Return object unchanged.

// Validate input object.
if (!FUZZ_GET_ATTR_INT(code_point, "alive")) { FUZZ_BAIL(); }
( void ) code_point->GetIndicConjunctBreakProperty();
// Return object unchanged.

// Build a small valid UTF-8 string composed of 1..4 valid Unicode scalars.
uint64_t r = *FUZZ_PARAM(uint64_t);
int count = static_cast<int>((r % 4) + 1); // 1..4 code points
std::string text; text.reserve(4 * count);
for (int i = 0; i < count; ++i) {
  uint32_t raw = static_cast<uint32_t>((r >> (i * 13)) & 0x1FFFFu); // take 17 bits chunks
  uint32_t scalar = raw % 0x110000u;
  if (scalar >= 0xD800u && scalar <= 0xDFFFu) scalar = 'C';
  if ((scalar & 0xFFFEu) == 0xFFFEu || (scalar >= 0xFDD0u && scalar <= 0xFDEFu)) scalar = 'D';
  if (scalar <= 0x7Fu) {
    text.push_back(static_cast<char>(scalar));
  } else if (scalar <= 0x7FFu) {
    text.push_back(static_cast<char>(0xC0 | ((scalar >> 6) & 0x1F)));
    text.push_back(static_cast<char>(0x80 | (scalar & 0x3F)));
  } else if (scalar <= 0xFFFFu) {
    text.push_back(static_cast<char>(0xE0 | ((scalar >> 12) & 0x0F)));
    text.push_back(static_cast<char>(0x80 | ((scalar >> 6) & 0x3F)));
    text.push_back(static_cast<char>(0x80 | (scalar & 0x3F)));
  } else {
    text.push_back(static_cast<char>(0xF0 | ((scalar >> 18) & 0x07)));
    text.push_back(static_cast<char>(0x80 | ((scalar >> 12) & 0x3F)));
    text.push_back(static_cast<char>(0x80 | ((scalar >> 6) & 0x3F)));
    text.push_back(static_cast<char>(0x80 | (scalar & 0x3F)));
  }
}

