// Move into a heap-allocated object so the fuzzer runtime can pool it safely.
YouCompleteMe::CodePointSequence *sequence = new YouCompleteMe::CodePointSequence(std::move(seq));
// Mark that the contained CodePoint* pointers have unknown/implementation-defined ownership.
FUZZ_SET_ATTR_INT(sequence, "contains_ephemeral_pointers", 1);
// Output the sequence pointer.

