// Contract: what() returns a non-null pointer valid for the lifetime of the exception.
FUZZ_ASSERT(msg != nullptr, "UnicodeDecodeError::what() returned null");
// Return the exception object unchanged.

// Create a random UTF-8 byte sequence to construct a Character from. The API
// expects a single grapheme cluster; we cannot guarantee that here, so we
// attempt construction and bail on any exception from decoding/normalization.
std::string raw = FUZZ_PARAM_STR();
// Keep input short for performance; slicing may split code points, which the
// constructor must handle (by throwing or internal handling).
size_t max_len = static_cast<size_t>(*FUZZ_PARAM(unsigned int) % 8 + 1);
if (raw.size() > max_len) raw.resize(max_len);

YouCompleteMe::Character *character = nullptr;
try {
  character = new YouCompleteMe::Character(std::string_view(raw));
} catch (const std::exception &) {
  FUZZ_BAIL();
}
// Track some properties to enable downstream validation and richer paths.
FUZZ_SET_ATTR_STR(character, "src", raw.c_str());
FUZZ_SET_ATTR_INT(character, "is_base", character->IsBase() ? 1 : 0);
FUZZ_SET_ATTR_INT(character, "is_letter", character->IsLetter() ? 1 : 0);
FUZZ_SET_ATTR_INT(character, "is_punct", character->IsPunctuation() ? 1 : 0);
FUZZ_SET_ATTR_INT(character, "is_upper", character->IsUppercase() ? 1 : 0);
// Persist the object by returning it as an output.

// Access the normalized form; do not keep the reference beyond this stub.
const std::string &norm = character->Normal();
// Record the length to exercise attribute tracking and downstream checks.
FUZZ_SET_ATTR_INT(character, "normal_len", static_cast<int>(norm.size()));
// character remains owned by the fuzzer pool and is returned as output.

// Access the base form and record its length for downstream usage.
const std::string &base = character->Base();
FUZZ_SET_ATTR_INT(character, "base_len", static_cast<int>(base.size()));
// Persist input object as output.

// Access the case-folded form and record its length for coverage/attrs.
const std::string &fold = character->FoldedCase();
FUZZ_SET_ATTR_INT(character, "fold_len", static_cast<int>(fold.size()));
// Persist input object as output.

// Access the case-swapped form and record its length for coverage/attrs.
const std::string &swapc = character->SwappedCase();
FUZZ_SET_ATTR_INT(character, "swap_len", static_cast<int>(swapc.size()));
// Persist input object as output.

// Query and store the base flag for downstream logic.
bool is_base = character->IsBase();
FUZZ_SET_ATTR_INT(character, "is_base", is_base ? 1 : 0);
// Persist input object as output.

// Query and store the letter flag for downstream logic.
bool is_letter = character->IsLetter();
FUZZ_SET_ATTR_INT(character, "is_letter", is_letter ? 1 : 0);
// Persist input object as output.

// Query and store the punctuation flag for downstream logic.
bool is_punct = character->IsPunctuation();
FUZZ_SET_ATTR_INT(character, "is_punct", is_punct ? 1 : 0);
// Persist input object as output.

