FUZZ_ASSERT(ab == ba, "operator== must be symmetric");
FUZZ_ASSERT((*lhs) == (*lhs), "operator== must be reflexive on lhs");
FUZZ_ASSERT((*rhs) == (*rhs), "operator== must be reflexive on rhs");
// Store last comparison result for potential downstream use.
