bool ba = rhs->EqualsIgnoreCase(*lhs);
FUZZ_ASSERT(ab == ba, "EqualsIgnoreCase must be symmetric");
FUZZ_SET_ATTR_INT(lhs, "last_ci_eq", ab ? 1 : 0);
FUZZ_SET_ATTR_INT(rhs, "last_ci_eq", ba ? 1 : 0);
// Return both inputs as outputs.

// Smart match is intentionally not symmetric; exercise both directions to
// increase coverage and store the outcomes as attributes.
