bool ba = rhs->MatchesSmart(*lhs);
FUZZ_SET_ATTR_INT(lhs, "last_smart_ab", ab ? 1 : 0);
FUZZ_SET_ATTR_INT(rhs, "last_smart_ba", ba ? 1 : 0);
// Keep both inputs alive by returning them as outputs.

