// or normalization exceptions to keep the harness safe and deterministic.
std::string raw = FUZZ_PARAM_STR();
// Limit size for performance.
size_t limit = static_cast<size_t>(*FUZZ_PARAM(unsigned int) % 128);
if (raw.size() > limit) raw.resize(limit);
try {
  std::string normalized = YouCompleteMe::NormalizeInput(std::string_view(raw));
  // Touch the result to avoid being optimized away.
  volatile size_t sink = normalized.size();
  (void)sink;
} catch (const std::exception &) {
  FUZZ_BAIL();
}

// Create a UTF-8 safe, bounded-size ASCII string to satisfy constructor requirements.
// We transform fuzz bytes to 7-bit ASCII to avoid malformed UTF-8.
std::string src = FUZZ_PARAM_STR();
size_t max_len = 2048; // keep allocations small for fuzzer perf
size_t take = std::min(src.size(), max_len);
// Optionally allow empty by selecting a prefix length in [0, take]
size_t want = (size_t)(*FUZZ_PARAM(unsigned int) % (take + 1));
std::string ascii;
ascii.reserve(want);
for (size_t i = 0; i < want; ++i) {
  unsigned char c = static_cast<unsigned char>(src[i]);
  ascii.push_back(static_cast<char>(c & 0x7F)); // force valid single-byte UTF-8
}
// Construct the Word by moving the string, as required by the API.
YouCompleteMe::Word *word = new YouCompleteMe::Word(std::move(ascii));
// Track basic liveness for downstream stubs.
FUZZ_SET_ATTR_INT(word, "constructed", 1);
// Validation: object created and owned by the pool via outputs. No further checks necessary.

// Access the character sequence. Reference remains valid while 'word' lives.
const YouCompleteMe::CharacterSequence &seq = word->Characters();
// Light-touch usage to exercise code paths.
size_t sz = seq.size();
(void)sz;
// If the word is empty, the sequence must be empty as well.
bool empty_flag = word->IsEmpty();
if (empty_flag) {
  FUZZ_ASSERT(seq.size() == 0, "Empty Word must have 0 Characters()");
}
// Return 'word' to the pool as it remains valid and owned by fuzzer runtime.
// Validation: respects lifetime of returned reference and returns the input to the pool.

// Access the underlying text. Reference remains valid while 'word' lives.
const std::string &t = word->Text();
// Light-touch usage to exercise code paths without copying large data.
volatile size_t sz = t.size();
