import random
from typing import List

# This generator produces valid UTF-8 text inputs tailored to exercise
# YouCompleteMe character/grapheme handling and matching paths. It favors
# single-grapheme clusters for Character, and longer identifier-like strings
# for Candidate/Word, mixing ASCII, Unicode letters, punctuation, combining
# marks, emoji, ZWJ sequences, and Indic script pieces. All outputs are valid
# UTF-8 and length-capped to <= 4096 bytes.

# Useful code point groups (inclusive ranges or explicit lists)
ASCII_LETTERS_LOWER = list(range(0x61, 0x7B))
ASCII_LETTERS_UPPER = list(range(0x41, 0x5B))
ASCII_DIGITS = list(range(0x30, 0x3A))
ASCII_PUNCT = [
    ord(c) for c in "-_./:+#@$%^&*()[]{}<>=!?,'\"|~`"
]
WHITESPACE = [0x20, 0x09, 0x0A, 0x0D]

# Combining marks to form multi-code-point grapheme clusters
COMBINING_MARKS = list(range(0x0300, 0x036F + 1)) + list(range(0x1AB0, 0x1AFF + 1))

# Common emoji and modifiers
EMOJI_BASE = [
    0x1F600, 0x1F603, 0x1F604, 0x1F60D, 0x1F618, 0x1F44D, 0x1F44E,
    0x1F9D1, 0x1F469, 0x1F468, 0x1F9B8, 0x2764, 0x1F4A9, 0x1F680,
]
EMOJI_ZWJ_COMPONENTS = [0x200D, 0x2640, 0x2642]
SKIN_TONES = [0x1F3FB, 0x1F3FC, 0x1F3FD, 0x1F3FE, 0x1F3FF]
ZWJ = 0x200D
ZWSP = 0x200B
ZWNJ = 0x200C

# Indic script consonants and matras (to exercise IndicConjunctBreak)
DEVANAGARI_CONSONANTS = list(range(0x0915, 0x0939 + 1))
DEVANAGARI_VOWEL_SIGNS = list(range(0x093E, 0x094D + 1))  # includes virama 0x094D
# Add a few other scripts letters
GREEK_LETTERS = list(range(0x0370, 0x03FF + 1))
CYRILLIC_LETTERS = list(range(0x0400, 0x04FF + 1))
LATIN_EXT = list(range(0x00C0, 0x024F + 1))

# Regional indicator flags to test grapheme segmentation
REGIONAL_INDICATORS = list(range(0x1F1E6, 0x1F1FF + 1))

# Helper: safely encode a code point to UTF-8 bytes

def _cp_to_utf8(cp: int) -> bytes:
    # Skip surrogates and invalid range
    if 0xD800 <= cp <= 0xDFFF:
        cp = 0xFFFD
    if cp < 0 or cp > 0x10FFFF:
        cp = 0xFFFD
    return chr(cp).encode('utf-8')

# Build a single user-perceived grapheme cluster

def _rand_base_letter(r: random.Random) -> int:
    pool = []
    pool += ASCII_LETTERS_LOWER + ASCII_LETTERS_UPPER
    pool += LATIN_EXT
    pool += GREEK_LETTERS
    pool += CYRILLIC_LETTERS
    return r.choice(pool)

def _rand_punctuation(r: random.Random) -> int:
    return r.choice(ASCII_PUNCT)

def _rand_digit(r: random.Random) -> int:
    return r.choice(ASCII_DIGITS)

def _rand_combining_sequence(r: random.Random, base_cp: int) -> bytes:
    b = bytearray(_cp_to_utf8(base_cp))
    # 0..3 combining marks
    for _ in range(r.randint(0, 3)):
        b += _cp_to_utf8(r.choice(COMBINING_MARKS))
    return bytes(b)

def _rand_emoji_cluster(r: random.Random) -> bytes:
    # base + optional skin tone + optional ZWJ sequence
    parts: List[int] = []
    base = r.choice(EMOJI_BASE)
    parts.append(base)
    if r.random() < 0.5 and base in (0x1F44D, 0x1F44E, 0x1F9D1, 0x1F469, 0x1F468, 0x1F9B8):
        parts.append(r.choice(SKIN_TONES))
    # build ZWJ family like person ZWJ profession
    if r.random() < 0.4:
        parts.append(ZWJ)
        parts.append(r.choice(EMOJI_BASE))
        if r.random() < 0.3:
            parts.append(r.choice(EMOJI_ZWJ_COMPONENTS))
    return b"".join(_cp_to_utf8(cp) for cp in parts)

def _rand_flag_sequence(r: random.Random) -> bytes:
    # flags are pairs of regional indicators
    return _cp_to_utf8(r.choice(REGIONAL_INDICATORS)) + _cp_to_utf8(r.choice(REGIONAL_INDICATORS))


def _rand_grapheme(r: random.Random) -> bytes:
    choice = r.random()
    if choice < 0.25:
        # simple base letter (possibly uppercase)
        return _cp_to_utf8(_rand_base_letter(r))
    elif choice < 0.50:
        # base letter with combining marks
        return _rand_combining_sequence(r, _rand_base_letter(r))
    elif choice < 0.65:
        # punctuation or digit
        if r.random() < 0.5:
            return _cp_to_utf8(_rand_punctuation(r))
        return _cp_to_utf8(_rand_digit(r))
    elif choice < 0.80:
        # emoji cluster
        return _rand_emoji_cluster(r)
    elif choice < 0.92:
        # flag sequence
        return _rand_flag_sequence(r)
    else:
        # Indic conjunct: consonant + virama + consonant + optional vowel sign
        cons1 = r.choice(DEVANAGARI_CONSONANTS)
        cons2 = r.choice(DEVANAGARI_CONSONANTS)
        virama = 0x094D
        parts = [_cp_to_utf8(cons1), _cp_to_utf8(virama), _cp_to_utf8(cons2)]
        if r.random() < 0.5:
            parts.append(_cp_to_utf8(r.choice(DEVANAGARI_VOWEL_SIGNS)))
        return b"".join(parts)

