        max_len = min_len
    min_len = max(0, int(min_len))
    max_len = max(min_len, int(max_len))

    parts: List[bytes] = []
    length = r.randint(min_len, max_len)
    for i in range(length):
        t = r.random()
        if t < 0.40:
            # ASCII letter; sometimes uppercase for camelCase
            cp = r.choice(ASCII_LETTERS_UPPER if (i > 0 and r.random() < 0.25) else ASCII_LETTERS_LOWER)
            parts.append(_cp_to_utf8(cp))
        elif t < 0.55:
            # digit
            parts.append(_cp_to_utf8(_rand_digit(r)))
        elif t < 0.70:
            # underscore or dash to create word boundaries
            parts.append(_cp_to_utf8(r.choice([ord('_'), ord('-')])))
        elif t < 0.85:
            # Unicode letter with optional combining marks
            parts.append(_rand_combining_sequence(r, _rand_base_letter(r)))
        else:
            # occasional emoji or flag to bring in non-letter bytes
            parts.append(_rand_emoji_cluster(r) if r.random() < 0.7 else _rand_flag_sequence(r))
    # occasionally insert ZWJ/ZWNJ/ZWSP inside to stress grapheme handling
    if len(parts) >= 2 and r.random() < 0.2:
        idx = r.randrange(1, len(parts))  # safe: len(parts) >= 2 ensures range is non-empty
        parts.insert(idx, _cp_to_utf8(r.choice([ZWJ, ZWNJ, ZWSP])))
    return b"".join(parts)

# Generate short string for Character::Character fuzz stub (expects one grapheme)

def _gen_for_character(r: random.Random) -> bytes:
    # Choose 1 grapheme cluster, maybe 2 rarely to test multi-grapheme input
    clusters = 1 if r.random() < 0.9 else 2
    bs = b"".join(_rand_grapheme(r) for _ in range(clusters))
    # Ensure very small size (<= 8) as the stub may trim
    if len(bs) > 8:
        bs = bs[:8]
    return bs

# Generate text for NormalizeInput fuzz stub (any UTF-8, up to ~128 bytes)

def _gen_for_normalize(r: random.Random) -> bytes:
    # Mix of words separated by punctuation/space
    parts: List[bytes] = []
    words = r.randint(1, 6)
    for w in range(words):
        # ensure max >= min to avoid randint issues
        max_len = r.randint(2, 8)
        if max_len < 1:
            max_len = 1
        parts.append(_rand_identifier(r, 1, max_len))
        if w != words - 1:
            sep = r.choice([b" ", b"-", b"_", b"/", b"::", _cp_to_utf8(0x00B7)])
            parts.append(sep)
    out = b"".join(parts)
    if len(out) > 128:
        out = out[:128]
    return out

# Generate text for Candidate-related stubs (up to 2048 bytes)

def _gen_for_candidate(r: random.Random) -> bytes:
    # Compose several identifier-like tokens with separators to create word boundaries
    parts: List[bytes] = []
    tokens = r.randint(1, 10)
    for t in range(tokens):
        min_len = r.randint(3, 10)
        max_len = r.randint(10, 40)
        if max_len < min_len:
            max_len = min_len
        parts.append(_rand_identifier(r, min_len, max_len))
        if t != tokens - 1:
            parts.append(r.choice([b"::", b"/", b".", b" ", b"-", b"_", _cp_to_utf8(0x2022)]))
    out = b"".join(parts)
    if len(out) > 2048:
        out = out[:2048]
    return out

# Top-level generate(seed) required by harness

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Randomly pick a target stub scenario: character, normalize, or candidate
    mode = r.random()
    if mode < 0.34:
        return _gen_for_character(r)
    elif mode < 0.67:
        return _gen_for_normalize(r)
    else:
        return _gen_for_candidate(r)
